function Input({label,name,value,type='text',required=true,...rest}){return <label>{label}<input name={name} type={type} defaultValue={value??''} required={required} min={type==='number'?0:undefined} step={type==='number'?'any':undefined} {...rest}/></label>}
function Relation({name,label,table,data,value,required=true,disabled=false}){return <label>{label}<select name={name} defaultValue={value||''} required={required} disabled={disabled}><option value="">Select {label.toLowerCase()}</option>{(data[table]||[]).map(r=><option key={r.id} value={r.id}>{fieldName(table,r)}{table==='invoices'?' · '+currency(r.total):''}</option>)}</select>{disabled&&<input type="hidden" name={name} value={value||''}/>}</label>}
function DynamicField({field,data,record,readonly}){const [key,label,type,options,required=true]=field;let value=record?.[key];if(type==='relation')return <Relation name={key} label={label} table={options} data={data} value={value} required={required} disabled={readonly}/>;if(type==='select')return <label>{label}<select name={key} defaultValue={value||options[0]}>{options.map(o=><option key={o}>{o}</option>)}</select></label>;if(type==='textarea')return <label>{label}<textarea name={key} defaultValue={value||''} required={required} rows={3}/></label>;if(type==='checkbox')return <label className="sf-checkbox"><input name={key} type="checkbox" defaultChecked={value??true}/>{label}</label>;if(type==='datetime-local'&&value){const d=new Date(value);value=new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)}return <Input label={label} name={key} type={type||'text'} value={value} required={required}/>}
function Busy(){return <div className="sf-empty"><RefreshCw className="sf-spin" size={26}/><h3>Loading records…</h3><p>Reading your permitted data from Supabase.</p></div>}
function Empty({icon:I=Package,title,text,action}){return <div className="sf-empty"><span className="sf-empty-icon"><I size={28}/></span><h3>{title}</h3><p>{text}</p>{action&&<button className="sf-btn" onClick={action}><Plus size={15}/>Get started</button>}</div>}
function PanelTitle({title,subtitle,icon:I,extra,action}){return <div className="sf-panel-title"><div><h2>{I&&<I size={18}/>} {title}</h2>{subtitle&&<p>{subtitle}</p>}</div>{action?<button onClick={action}>View all<ArrowRight size={13}/></button>:extra?<span>{extra}</span>:null}</div>}
function Shipments({rows,data,ready,loading,select,book}){return loading?<Busy/>:rows.length?<div className="sf-table-scroll"><table><thead><tr><th>Tracking number</th><th>Customer</th><th>Destination</th><th>Weight</th><th>Status</th><th>Action</th></tr></thead><tbody>{rows.map(s=>{const o=(data.orders||[]).find(o=>o.id===s.order_id);const c=(data.clients||[]).find(c=>c.id===o?.client_id);return <tr key={s.id}><td><button className="sf-text" onClick={()=>select(s)}><Box size={16}/>{s.tracking_number}</button></td><td>{c?.name||'—'}</td><td>{s.destination}</td><td>{s.weight||0} kg</td><td><Status value={s.status}/></td><td><button className="sf-btn tiny" onClick={()=>select(s)}>View</button></td></tr>})}</tbody></table></div>:<Empty icon={Package} title="Your next shipment starts here" text={ready?'No shipments yet. Create an order or book a marketplace service.':'Connect your backend to view real shipment records.'} action={book}/>}
function Records({cfg,rows,data,area,staff,onInspect,onEdit,onDelete,canDelete,onProgress,onVerify,onModerate}){const skip=new Set(['id','workspace_id','user_id','details','actor_id','submitted_by','verified_by']);let columns=Object.keys(rows[0]).filter(k=>!skip.has(k)&&rows.some(r=>r[k]!==null));if(cfg.table==='workspaces')columns=['name','email','country','status','created_at'];if(cfg.table==='shipments')columns=['tracking_number','origin','destination','weight','mode','status'];if(cfg.table==='invoices')columns=['number','total','status','created_at'];if(cfg.table==='tickets')columns=['subject','type','status','response','created_at'];if(cfg.table==='services')columns=['name','mode','origin','destination','base_price','per_kg','active'];columns=columns.slice(0,7);
 const canEdit=!cfg.readonly&&!cfg.noEdit&&(area==='platform'||area==='company'&&staff&&(!['subscriptions','plans','billing_payments','contact_messages'].includes(cfg.table))||area==='customer'&&cfg.table==='addresses');
 const canCreateDelete=canDelete&&!cfg.readonly&&!cfg.editOnly&&!cfg.noDelete&&!['invoices','payments'].includes(cfg.table);
 return <div className="sf-table-scroll"><table><thead><tr>{columns.map(k=><th key={k}>{k.replaceAll('_',' ')}</th>)}<th>Actions</th></tr></thead><tbody>{rows.map(r=><tr key={r.id}>{columns.map(k=><td key={k}>{k==='status'?<Status value={r[k]}/>:k==='active'?<Status value={r[k]?'active':'inactive'}/>:k.endsWith('_at')?time(r[k]):['total','amount','value','monthly_price','base_price','per_kg'].includes(k)?currency(r[k]):k.endsWith('_id')?short(r[k]):typeof r[k]==='object'?JSON.stringify(r[k]):<span className={k===cfg.key?'sf-key':''}>{String(r[k]??'—')}</span>}</td>)}<td><div className="sf-row-actions"><button className="sf-icon" title="Inspect" aria-label="Inspect record" onClick={()=>onInspect(r)}><Eye size={16}/></button>{canEdit&&<button className="sf-icon" title="Edit" aria-label="Edit record" onClick={()=>onEdit(r)}><Pencil size={15}/></button>}{canCreateDelete&&<button className="sf-icon" title="Delete" aria-label="Delete record" onClick={()=>onDelete(r)}><Trash2 size={15}/></button>}{cfg.table==='shipments'&&staff&&r.status!=='Delivered'&&<button className="sf-btn tiny" onClick={()=>onProgress(r)}>Next stage<ArrowRight size={12}/></button>}{cfg.table==='payments'&&staff&&r.status==='submitted'&&<><button className="sf-btn tiny" onClick={()=>onVerify(r,'verified')}>Verify</button><button className="sf-btn tiny" onClick={()=>onVerify(r,'rejected')}>Reject</button></>}{cfg.table==='reviews'&&area==='platform'&&r.status==='pending'&&<><button className="sf-btn tiny" onClick={()=>onModerate(r,'approved')}>Approve</button><button className="sf-btn tiny" onClick={()=>onModerate(r,'rejected')}>Reject</button></>}</div></td></tr>)}</tbody></table></div>}
function Donut({stats}){const values=stats?[stats.pending,stats.processing,stats.in_transit,stats.delivered]:[0,0,0,0],total=values.reduce((a,b)=>a+Number(b||0),0);let acc=0;return <div className="sf-donut-wrap"><div className="sf-donut"><svg viewBox="0 0 140 140"><circle cx="70" cy="70" r="54" fill="none" stroke="var(--sf-grid)" strokeWidth="16"/>{values.map((v,i)=>{const dash=total?v/total*339.292:0;const offset=acc;acc+=dash;return <circle key={i} cx="70" cy="70" r="54" fill="none" stroke={color[i]} strokeWidth="16" strokeDasharray={`${dash} 339.292`} strokeDashoffset={-offset} transform="rotate(-90 70 70)"/>})}</svg><div><b>{stats?total:'—'}</b><small>Total shipments</small></div></div><div className="sf-legend">{stages.map((s,i)=><div key={s}><i style={{background:color[i]}}/><span>{s}</span><b>{stats?values[i]:'—'}</b><small>{total?'('+Math.round(values[i]/total*100)+'%)':''}</small></div>)}</div></div>}
function Volume({rows}){if(!rows.length)return <Empty icon={BarChart3} title="Volume follows your shipments" text="This chart plots real daily totals over the last 14 days."/>;const max=Math.max(1,...rows.map(x=>x.total));return <div className="sf-volume"><div className="sf-chart-legend"><span><i/>Total</span><span><i/>Delivered</span></div><svg viewBox="0 0 500 180" role="img" aria-label="Shipment volume over the last 14 days">{[0,1,2,3].map(i=><g key={i}><line x1="35" x2="490" y1={20+i*42} y2={20+i*42} stroke="var(--sf-grid)"/><text x="3" y={24+i*42} fill="var(--sf-muted)" fontSize="10">{Math.round(max*(1-i/3))}</text></g>)}{rows.map((r,i)=>{const width=Math.min(30,400/rows.length);const x=45+i*440/Math.max(1,rows.length);return <g key={r.day}><rect x={x} y={146-r.total/max*126} width={width} height={r.total/max*126} rx="3" fill="#158aff" opacity=".85"/><rect x={x+width*.35} y={146-r.delivered/max*126} width={width*.5} height={r.delivered/max*126} rx="2" fill="#15c89c"/><title>{r.day}: {r.total} shipments, {r.delivered} delivered</title>{(i===0||i===rows.length-1||rows.length<6)&&<text x={x} y="167" fill="var(--sf-muted)" fontSize="9">{r.day.slice(5)}</text>}</g>})}</svg></div>}
function LocationsMap({shipments,onSelect}){const located=shipments.filter(s=>Number.isFinite(s.latitude)&&Number.isFinite(s.longitude));const s=located[0];return s?<div className="sf-live-map"><iframe title="Latest GPS position" src={'https://www.openstreetmap.org/export/embed.html?bbox='+[s.longitude-.2,s.latitude-.2,s.longitude+.2,s.latitude+.2].join('%2C')+'&layer=mapnik&marker='+s.latitude+'%2C'+s.longitude}/><div>{located.slice(0,4).map(s=><button key={s.id} onClick={()=>onSelect(s)}><Navigation size={13}/>{s.tracking_number}<span>{time(s.gps_at)}</span></button>)}</div></div>:<div className="sf-map-empty"><div className="sf-map-grid"/><MapPin size={29}/><h3>Waiting for a real GPS position</h3><p>Authorized devices can share shipment locations.<br/>No locations are simulated.</p></div>}
function ShipmentDetail({shipment:s,api,close,progress,gps,shareGps,staff,print}){const events=(api.data.tracking_events||[]).filter(e=>e.shipment_id===s.id).sort((a,b)=>new Date(a.created_at)-new Date(b.created_at));return <section className="sf-panel sf-shipment-detail"><PanelTitle icon={Truck} title={s.tracking_number} subtitle={s.origin+' → '+s.destination}/><button className="sf-detail-close sf-icon" aria-label="Close shipment" onClick={close}><X size={18}/></button><div className="sf-detail-grid"><div><div className="sf-button-row"><Status value={s.status}/>{staff&&s.status!=='Delivered'&&<button className="sf-btn primary" onClick={()=>progress(s)}>Move to {stages[stages.indexOf(s.status)+1]}<ArrowRight size={14}/></button>}<button className="sf-btn" onClick={print}><Printer size={15}/>Shipping document</button></div><h3>Tracking timeline</h3><div className="sf-timeline">{events.length?events.map(e=><div key={e.id}><span><Check size={13}/></span><div><b>{e.status}</b><p>{e.message}</p><small>{time(e.created_at)} EAT</small></div></div>):<p>No loaded timeline events. Refresh to fetch the latest milestones.</p>}</div></div><div><LocationsMap shipments={[s]} onSelect={()=>{}}/>{s.gps_at&&<p className="sf-gps-time">Last position: {time(s.gps_at)} EAT</p>}{staff&&<><p className="sf-location-note">Shares this device’s precise location with authorized shipment viewers. The map provider receives the displayed coordinates.</p><button className="sf-btn" onClick={()=>shareGps(s)}><Navigation size={15}/>{gps?'Stop sharing this device’s GPS':'Share this device’s GPS'}</button></>}</div></div></section>}
function Booking({data,initialService,session,display}){const [service,setService]=useState(initialService?.id||''),[weight,setWeight]=useState('');const available=(data.services||[]).filter(s=>s.active&&(data.workspaces||[]).find(w=>w.id===s.workspace_id)?.status==='active');const s=available.find(s=>s.id===service);return <><p>Choose an approved cargo company’s service. The database computes the final amount from its published rate.</p><label>Service<select name="service" required value={service} onChange={e=>setService(e.target.value)}><option value="">Select a service</option>{available.map(s=><option key={s.id} value={s.id}>{(data.workspaces||[]).find(w=>w.id===s.workspace_id)?.name} · {s.name} · {s.origin} → {s.destination}</option>)}</select></label>{!available.length&&<div className="sf-info">No active services are loaded. A cargo company must publish a service first.</div>}<label>Weight (kg)<input type="number" name="weight" required min="0.01" max="100000" step="0.01" value={weight} onChange={e=>setWeight(e.target.value)}/></label>{s&&<div className="sf-quote"><span>Published rate: {currency(s.base_price)} + {currency(s.per_kg)}/kg</span><b>{currency(Number(s.base_price)+Number(s.per_kg)*Number(weight||0))}</b></div>}<div className="sf-form-grid"><Input name="sender_name" label="Sender name" value={display}/><Input name="sender_email" label="Sender email" type="email" value={session?.user.email}/><Input name="sender_phone" label="Sender phone"/><Input name="origin" label="Pickup address"/><Input name="recipient_name" label="Recipient name"/><Input name="recipient_phone" label="Recipient phone"/></div><Input name="destination" label="Full delivery address"/></>}
function Marketplace({api,book}){const [q,setQ]=useState('');const services=(api.data.services||[]).filter(s=>s.active&&(s.name+' '+s.origin+' '+s.destination).toLowerCase().includes(q.toLowerCase()));return <section><div className="sf-panel sf-table-toolbar"><Store size={20}/><input aria-label="Search services" placeholder="Search routes, cities or service…" value={q} onChange={e=>setQ(e.target.value)}/></div><div className="sf-service-grid">{services.map(s=><article className="sf-panel sf-service" key={s.id}><span className="sf-service-icon"><Truck size={26}/></span><Status value={s.mode}/><h2>{s.name}</h2><p>{(api.data.workspaces||[]).find(w=>w.id===s.workspace_id)?.name||'Cargo company'}</p><div className="sf-route"><MapPin size={15}/>{s.origin}<ArrowRight size={15}/>{s.destination}</div><h3>{currency(s.base_price)} <small>+ {currency(s.per_kg)} / kg</small></h3><button className="sf-btn primary full" onClick={()=>book(s)}>Book this service<ArrowRight size={16}/></button></article>)}</div>{!services.length&&<section className="sf-panel"><Empty icon={Store} title="A marketplace for independent cargo companies" text="Approved cargo companies publish their real services, routes and prices here."/></section>}</section>}
function Team({api,area,add}){const [rows,setRows]=useState([]),[w,setW]=useState(api.tenant||'');useEffect(()=>{if(!api.db||!api.session)return;let q=api.db.from('sl_memberships').select('*');if(area==='company')q=q.eq('workspace_id',api.tenant);else if(w)q=q.eq('workspace_id',w);q.then(r=>{if(r.error)api.setError(r.error.message);else setRows(r.data)})},[api.db,api.session,api.tenant,w,api.data]);const can=area==='platform'||api.member?.role==='admin';return <section className="sf-panel"><div className="sf-panel-title"><div><h2>Workspace memberships</h2><p>Roles are stored in protected membership rows. Platform admin assignment requires trusted SQL.</p></div>{can&&<button className="sf-btn primary" onClick={add}><Plus size={15}/>Add member</button>}</div>{area==='platform'&&<div className="sf-table-toolbar"><select value={w} onChange={e=>setW(e.target.value)}><option value="">All companies</option>{(api.data.workspaces||[]).map(t=><option key={t.id} value={t.id}>{t.name}</option>)}</select></div>}<div className="sf-table-scroll"><table><thead><tr><th>User ID</th><th>Cargo company</th><th>Role</th><th>Actions</th></tr></thead><tbody>{rows.map(r=><tr key={r.workspace_id+r.user_id}><td>{r.user_id}</td><td>{(api.data.workspaces||[]).find(w=>w.id===r.workspace_id)?.name||short(r.workspace_id)}</td><td><Status value={r.role}/></td><td>{can&&r.user_id!==api.session?.user.id&&<button className="sf-btn tiny" onClick={()=>api.mutate(()=>api.db.rpc('sl_remove_member',{w:r.workspace_id,member:r.user_id}),'Member removed.')}>Remove access</button>}</td></tr>)}</tbody></table></div>{!rows.length&&<Empty icon={Shield} title="No memberships loaded" text="Company administrators can add confirmed existing users."/>}</section>}
function PrintDocument({type,record:r,data}){const s=type==='shippingDocument'?r:null;const o=(data.orders||[]).find(o=>o.id===(s?.order_id||r.order_id));const c=(data.clients||[]).find(c=>c.id===o?.client_id);const w=(data.workspaces||[]).find(w=>w.id===r.workspace_id);return <><div className="sf-print-document"><header><div><h1>{w?.name||'Cargo company'}</h1><p>{w?.address||''}<br/>{w?.email||''} {w?.phone||''}</p></div><div><h2>{s?'SHIPPING DOCUMENT':'INVOICE'}</h2><b>{s?.tracking_number||r.number}</b><p>{time(r.created_at)} EAT</p></div></header><div className="sf-print-parties"><div><small>{s?'SHIPPER':'BILL TO'}</small><h3>{c?.name||'Customer'}</h3><p>{c?.address}<br/>{c?.email}<br/>{c?.phone}</p></div>{s&&<div><small>CONSIGNEE</small><h3>{s.recipient_name||'—'}</h3><p>{s.destination}<br/>{s.recipient_phone}</p></div>}</div><table><thead><tr><th>Description</th><th>{s?'Weight':'Order'}</th><th>Amount (TZS)</th></tr></thead><tbody><tr><td>{o?.description||s?.mode||'Freight service'}</td><td>{s?s.weight+' kg':o?.reference||short(r.order_id)}</td><td>{currency(s?o?.value:r.total)}</td></tr></tbody></table><div className="sf-print-total"><p>{s?'Origin: '+s.origin:'Payment status: '+r.status}</p><h2>{currency(s?o?.value:r.total)}</h2></div><footer>Generated from stored records · {s?.tracking_number||r.number}<br/>Payment references require verification. This document does not confirm receipt of payment unless the invoice is marked paid.</footer></div><button className="sf-btn primary" onClick={()=>window.print()}><Printer size={16}/>Print / save as PDF</button></>}
